/**
 * ML results showcase: out-of-sample validation results (2023) of modules A, B and D.
 *
 * Generated by research/ml-showcase/analysis.py from the saved predictions and the frozen
 * models' reports, then served as a static file. Aggregates only, no row-level data.
 * These are validation results, not forecasts: no model serves predictions.
 */

export interface MetricWithInterval {
  value: number;
  ci95: [number, number] | null;
  months: number;
}

export interface HorizonResult {
  horizon: number;
  rows: number;
  model: number;
  baselines: Record<string, number>;
  bias_model: number | null;
  bias_best_baseline: number | null;
  rmse_model?: number | null;
  rmse_best_baseline?: number | null;
}

export interface MonthlyResult {
  horizon: number;
  month: string; // YYYY-MM, target month
  actual: number;
  model: number;
  baseline: number;
  model_error: number;
  baseline_error: number;
}

export interface DecileResult {
  decile: number;
  rows: number;
  level_min: number;
  level_max: number;
  model: number;
  baseline: number;
}

export interface EntityResult {
  entity: string;
  volume: number;
  rows: number;
  model: number;
  baseline: number;
  bias_model: number | null;
}

export interface ExamplePoint {
  date?: string;
  month?: string;
  actual: number;
  model: number;
  baseline: number;
}

export interface Example {
  entity: string;
  model: number;
  baseline: number;
  points: ExamplePoint[];
}

export interface ShowcaseTask {
  title: string;
  unit: string;
  rows: number;
  /** "WAPE" or "seat-weighted MAE". */
  metric: string;
  lightgbm: MetricWithInterval;
  baselines: Record<string, MetricWithInterval>;
  best_baseline: string;
  difference_vs_best_baseline: MetricWithInterval;
  beats_best_baseline: boolean;
  bias: MetricWithInterval;
  best_iteration: number;
  rows_fit: number;
  top_features_by_gain: Record<string, number>;
  by_horizon: HorizonResult[];
  by_volume_decile: DecileResult[];
  by_market: { market: string; rows: number; model: number; baseline: number }[];
  by_weekday?: { weekday: string; model: number; baseline: number }[];
  by_entity: EntityResult[];
  residuals: {
    unit: string;
    edges: number[];
    model: number[];
    baseline: number[];
    rows: number;
    model_quantiles: Record<"p10" | "p50" | "p90", number>;
    baseline_quantiles: Record<"p10" | "p50" | "p90", number>;
  };
  monthly: MonthlyResult[];
  examples: { best: Example; worst: Example } | null;
  scatter: { actual: number; model: number }[];
}

export type TaskKey = "a" | "b" | "d_pax" | "d_seats";

export interface Showcase {
  version: number;
  evaluated_on: string;
  tasks: Record<TaskKey, ShowcaseTask>;
  eda: Record<string, unknown>;
}

export const SHOWCASE_URL = "/ml/showcase.json";
export const REPORT_URL = "/ml/report.pdf";

let cached: Promise<Showcase> | null = null;

/** One request per session; a failure is not cached, so a retry can succeed. */
export function loadShowcase(fetchImpl: typeof fetch = (...args) => fetch(...args)): Promise<Showcase> {
  cached ??= fetchImpl(SHOWCASE_URL, { headers: { Accept: "application/json" } })
    .then((res) => {
      if (!res.ok) throw new Error(`The ML results could not be loaded (${res.status})`);
      return res.json() as Promise<Showcase>;
    })
    .catch((err: unknown) => {
      cached = null;
      throw err instanceof Error ? err : new Error(String(err));
    });
  return cached;
}

/** For tests. */
export function resetShowcaseCache() {
  cached = null;
}

/** WAPE as a percentage, load-factor MAE in percentage points. */
export function formatError(task: Pick<ShowcaseTask, "metric">, value: number | null | undefined, digits = 2): string {
  if (value == null || !Number.isFinite(value)) return "—";
  const scaled = (value * 100).toFixed(digits);
  return task.metric === "WAPE" ? `${scaled}%` : `${scaled} pts`;
}

/** A signed difference between two errors, in the metric's unit. */
export function formatDifference(task: Pick<ShowcaseTask, "metric">, value: number): string {
  const scaled = (value * 100).toFixed(2);
  const sign = value > 0 ? "+" : "";
  return task.metric === "WAPE" ? `${sign}${scaled} pts of WAPE` : `${sign}${scaled} pts`;
}
